import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"后端服务如何组织","description":"从一次请求的完整旅程理解 API、认证、业务服务、数据访问与异步任务的职责边界。","frontmatter":{"title":"后端服务如何组织","description":"从一次请求的完整旅程理解 API、认证、业务服务、数据访问与异步任务的职责边界。"},"headers":[],"relativePath":"backend/overview.md","filePath":"backend/overview.md","lastUpdated":1786262003000}'),n={name:"backend/overview.md"};function l(p,s,h,r,d,k){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="后端服务如何组织" tabindex="-1">后端服务如何组织 <a class="header-anchor" href="#后端服务如何组织" aria-label="Permalink to &quot;后端服务如何组织&quot;">​</a></h1><p>后端不是“接收请求后查数据库”的一段代码，而是一组把输入变成可靠业务结果的边界。理解一次请求如何流动，比记住某个框架目录更重要。</p><h2 id="一次请求的基本旅程" tabindex="-1">一次请求的基本旅程 <a class="header-anchor" href="#一次请求的基本旅程" aria-label="Permalink to &quot;一次请求的基本旅程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端请求</span></span>
<span class="line"><span>  → 路由与参数解析</span></span>
<span class="line"><span>  → 认证和权限检查</span></span>
<span class="line"><span>  → 业务服务与领域规则</span></span>
<span class="line"><span>  → 数据访问 / 外部服务</span></span>
<span class="line"><span>  → 响应、日志与指标</span></span></code></pre></div><p>每一层回答不同的问题：路由决定入口；认证确认“你是谁”；授权确认“你能做什么”；业务服务决定规则；数据层负责持久化；边缘层把结果变成协议响应。</p><h2 id="不要把所有逻辑塞进控制器" tabindex="-1">不要把所有逻辑塞进控制器 <a class="header-anchor" href="#不要把所有逻辑塞进控制器" aria-label="Permalink to &quot;不要把所有逻辑塞进控制器&quot;">​</a></h2><p>控制器或 handler 应保持薄：解析输入、调用业务服务、转换响应。业务规则放进可测试的服务层，数据查询放进仓储或模型层。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createOrderHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> input</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> parseCreateOrder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(request.body)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> order</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orderService.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input, request.user)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> toOrderResponse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(order)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这样同一套业务服务可以被 HTTP、定时任务、消息消费者等不同入口复用，规则也不会因为入口增加而复制。</p><h2 id="同步路径只做用户正在等待的事" tabindex="-1">同步路径只做用户正在等待的事 <a class="header-anchor" href="#同步路径只做用户正在等待的事" aria-label="Permalink to &quot;同步路径只做用户正在等待的事&quot;">​</a></h2><p>用户提交订单、保存资料等需要立即得到结果的操作，保留在同步请求中。发送通知、生成报表、同步非关键系统等耗时工作，适合进入可重试的异步任务。</p><table tabindex="0"><thead><tr><th>放在请求内</th><th>放到后台任务</th></tr></thead><tbody><tr><td>输入校验、权限判断、核心写入</td><td>邮件、推送、文件处理、批量同步</td></tr><tr><td>返回用户必须立即知道的结果</td><td>可延后、可重试、耗时较长的工作</td></tr></tbody></table><p>异步不是“扔出去就不管”。任务需要状态、重试上限、失败告警和幂等策略。</p><h2 id="组织服务时的检查表" tabindex="-1">组织服务时的检查表 <a class="header-anchor" href="#组织服务时的检查表" aria-label="Permalink to &quot;组织服务时的检查表&quot;">​</a></h2><ul><li>输入是否在入口处校验并转成明确类型？</li><li>权限规则是否在业务操作前执行？</li><li>一次业务操作的事务边界是否清楚？</li><li>外部调用失败、超时或重复到达时会发生什么？</li><li>日志是否能关联到一次请求和一个业务对象？</li></ul><p>服务边界清楚后，再讨论框架、数据库和部署方案，团队会有更稳定的共同语言。</p>`,16)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
